{"code": "# Check all directories
data_dir = pathlib.Path('data/web_scraped_small')
all_images = list(data_dir.glob('*/*.jpg'))
print(f"Total images found: {len(all_images)}")

# Group by directory
from collections import defaultdict
by_dir = defaultdict(list)
for img in all_images:
    by_dir[img.parent.name].append(img)

for dir_name, images in by_dir.items():
    print(f"\n{dir_name}: {len(images)} images")
    # Check first few images in each directory
    valid_count = 0
    for i, img in enumerate(images[:5]):
        try:
            PIL.Image.open(str(img))
            valid_count += 1
        except:
            pass
    print(f"  Valid images (sampled): {valid_count}/5")"}

